def elevation(bid,num,wall,rows,cols,trim='brown stone',cornice='brackets',escape=True,idx=0,**kw):
 b=DATA[bid];f=deepcopy(b['frontages'][idx]);fid=f'{bid}:{idx}';h=kw.pop('height',b['height']);bottom=kw.pop('bottom',3.95);wh=kw.pop('windowHeight',1.8);step=kw.pop('step',(h-bottom-wh-.95)/max(1,rows-1));positions=kw.pop('positions',[(c+.5)/cols for c in range(cols)])
 sources=[k for k,v in OBS['sources'].items() if fid in v.get('faceIds',[])]
 s={'number':num,'rows':rows,'upperBottom':bottom,'step':step,'cornice':cornice,'trim':'eb '+trim,'head':'molded',**kw}
 a={'wall':wall if wall.startswith('painted') else 'eb '+wall,'windows':[],'doors':[],'returnShops':[],'observedGround':{'replaceWindows':False,'replaceDoors':False},'e10Block':s,'observation':{'sources':sources,'facts':[t for k in sources for t in OBS['sources'][k]['observations']],'unknown':OBS['limits']}}
 for row in range(rows):
  for col,at in enumerate(positions):win(a,f,at,bottom+row*step,kw.get('windowWidth',min(1.08,f['length']/cols*.54)),wh,row=row,col=col)
 if escape:s['escape']={'span':kw.get('escapeSpan',[.27,.74]),'levels':[bottom-.17+i*step for i in range(rows)],'material':'eb '+kw.get('escapeColor','iron'),'dropAt':kw.get('dropAt',.68),'ornament':kw.get('escapeOrnament','plain'),'balconyOnly':kw.get('balconyOnly',False)}
 r={'faceId':fid,'buildingId':bid,'frontageIndex':idx,'address':str(num),'sourceFace':f,'sourceHeight':b['height'],'buildingHeight':h,'architecture':a};E.append(r);BY[str(num)]=(a,f);return a,f

def win(a,f,at,y,w,h,**kw):
 a['windows'].append({'at':at,'width':w/f['length'],'bottom':y,'height':h,'frame':'eb sash','trim':a['e10Block']['trim'],'hood':'none','rails':[.49],**kw})
def door(num,at=.5,w=1.12,low=.17,top=3.25,mat='dark wood',**kw):
 a,f=BY[num];d={'at':at,'width':w/f['length'],'bottom':low,'top':top,'leafTop':top-.45,'material':'eb '+mat,'trim':a['e10Block']['trim'],'recess':.30,'leaves':1,'hardware':'eb gold metal','panels':[{'y':.65,'height':.50,'width':.74,'glass':True},{'y':.17,'height':.22,'width':.74}],**kw};a['doors'].append(d);return d

def access(num,at=.5,rise=.65,width=1.5,depth=1.2,wells=(),**kw):
 a,f=BY[num];a['e10Block']['access']={'at':at,'rise':rise,'width':width,'depth':depth,**kw}
 a['observedGround']['basementAreaways']=[{'at':(lo+hi)/2,'width':hi-lo,'depth':.9,'depthBelow':.65} for lo,hi in wells]

def residential(num,at=.5,rise=.7,top=3.6,positions=(.18,.82),ww=1.45,**kw):
 a,f=BY[num];door(num,at,low=rise,top=top,**kw)
 for x in positions:win(a,f,x,rise+.38,ww,top-rise-.40,grille=True)
 access(num,at,rise,depth=max(.45,rise*1.7))
def shop(num,name,span,kind,panels,identity,frame='dark wood',**kw):
 a,f=BY[num];r=next(r for r in E if r['architecture'] is a);key=r['faceId']+':'+kind
 d={'top':3.10,'head':2.82,'base':.35,'recess':.24,'transom':False,'panels':panels,'signs':[],'detail09':{'id':key,'frame':'eb '+frame,'surround':'eb '+frame,'frameWidth':.045,'pierWidth':.065,'floor':.17,'molding':True,'displayDepth':1.,'doorSolidTop':.22,'displays':[],'furniture':[],'identity':identity,'sourceIds':a['observation']['sources']},'detailE10Block':{'kind':kind},**kw}
 a['returnShops'].append({'name':name,'span':span,'design':d});SHOPS.append({'id':key,'faceId':r['faceId'],'name':name,'businessId':kind,'span':span,'identity':identity,'sourceIds':a['observation']['sources'],'reviewState':'authored; served comparison pending'});return d

